<?php
namespace App\Console\Commands\Commercial;use App\Models\Tenant;use Database\Seeders\HelpdeskDemoSeeder;use Illuminate\Console\Command;use Illuminate\Support\Facades\Artisan;
class ResetDemoCommand extends Command{protected $signature='demo:reset {tenant}';protected $description='Rebuild an explicitly allow-listed demo tenant';public function handle():int{$id=(string)$this->argument('tenant');if(!config('promptbot.demo_mode')||!in_array($id,config('promptbot.demo_tenant_ids'),true)){$this->error('Demo reset is disabled or this tenant is not allow-listed.');return self::FAILURE;}$tenant=Tenant::findOrFail($id);tenancy()->initialize($tenant);try{Artisan::call('migrate:fresh',['--database'=>'tenant','--path'=>'database/migrations/tenant','--force'=>true]);Artisan::call('db:seed',['--class'=>'Database\\Seeders\\TenantDatabaseSeeder','--force'=>true]);app(HelpdeskDemoSeeder::class)->run();$this->info("Demo tenant {$id} reset.");return self::SUCCESS;}finally{tenancy()->end();}}}
